alter table public.files add constraint files_storage_path_safe_ck check (storage_path !~ '(^|/)\.\.(/|$)' and storage_path !~ '^/');
create unique index if not exists files_admin_bucket_path_uq on public.files(administration_id,storage_bucket,storage_path);
comment on table public.files is 'Authoritative metadata for private Habitex files. Object bytes remain in private Supabase Storage; access should use short-lived signed URLs generated by trusted backend code.';